def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position"))
    opp_pos = pos(observation.get("opponent_position"), self_pos)
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = max(corners, key=lambda c: md(c, opp_pos) * 2 + md(c, self_pos))
            return step_away(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for t in targets:
            p = pos(t, None)
            if p is None:
                continue
            score = md(self_pos, p) * 2 + max(0, 6 - md(opp_pos, p))
            if best is None or score < best_score:
                best = p
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for r in resources:
        p = pos(r, None)
        if p is None:
            continue
        score = md(self_pos, p) * 3 - md(opp_pos, p)
        if best is None or score < best_score:
            best = p
            best_score = score
    if best is not None:
        return step_toward(self_pos, best)

    # Fallback: pressure opponent or move to center if known.
    if gw > 0 and gh > 0:
        center = (gw // 2, gh // 2)
        if md(self_pos, opp_pos) <= 2:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, center)
    return step_toward(self_pos, opp_pos)

